Skill 1 rows look like constant shifts of each other (additive mod 8), while skills 2 and 3 have high-mode rows and columns (one input overriding the other). I will compare additive, xor, priority and co-cluster rule tables on 20% of the known pairs held back.
```python
import numpy as np
Ms=np.load("Ms.npy")
def split(M,seed=0):
    A,B=np.where(M>=0); r=np.random.RandomState(seed); p=r.permutation(len(A)); n=len(A)//5
    return (A[p[n:]],B[p[n:]],M[A[p[n:]],B[p[n:]]]),(A[p[:n]],B[p[:n]],M[A[p[:n]],B[p[:n]]])
def fit_group(tr,op,inv,restarts=30,seed=0):
    A,B,Y=tr; best=None; r=np.random.RandomState(seed)
    for _ in range(restarts):
        f=r.randint(0,8,32); g=r.randint(0,8,32)
        for it in range(30):
            for i in range(32):
                k=A==i
                if k.any(): f[i]=np.bincount(inv(Y[k],g[B[k]]),minlength=8).argmax()
            for j in range(32):
                k=B==j
                if k.any(): g[j]=np.bincount(inv(Y[k],f[A[k]]),minlength=8).argmax()
        s=(op(f[A],g[B])==Y).mean()
        if best is None or s>best[0]: best=(s,f.copy(),g.copy())
    return best
add=(lambda x,y:(x+y)%8, lambda y,o:(y-o)%8)
xor=(lambda x,y:x^y, lambda y,o:y^o)
def fit_priority(tr,seed=0,restarts=10):
    A,B,Y=tr; r=np.random.RandomState(seed); best=None
    for _ in range(restarts):
        f=np.array([np.bincount(Y[A==i],minlength=8).argmax() if (A==i).any() else 0 for i in range(32)])
        g=np.array([np.bincount(Y[B==j],minlength=8).argmax() if (B==j).any() else 0 for j in range(32)])
        p=r.rand(32);q=r.rand(32)
        pred=lambda A,B,f,g,p,q: np.where(p[A]>=q[B],f[A],g[B])
        for it in range(25):
            for i in range(32):
                k=A==i
                if not k.any(): continue
                bs=-1
                for c in range(8):
                    # candidate threshold values
                    for t in list(np.unique(q))+[-1,2]:
                        pv=np.where(t>=q[B[k]],c,g[B[k]])
                        sc=(pv==Y[k]).sum()
                        if sc>bs: bs=sc;f[i]=c;p[i]=t+1e-6*r.rand()
            for j in range(32):
                k=B==j
                if not k.any(): continue
                bs=-1
                for c in range(8):
                    for t in list(np.unique(p))+[-1,2]:
                        pv=np.where(p[A[k]]>=t,f[A[k]],c)
                        sc=(pv==Y[k]).sum()
                        if sc>bs: bs=sc;g[j]=c;q[j]=t-1e-6*r.rand()
        s=(pred(A,B,f,g,p,q)==Y).mean()
        if best is None or s>best[0]: best=(s,f.copy(),g.copy(),p.copy(),q.copy())
    return best
for s in range(4):
    tr,va=split(Ms[s])
    for nm,(op,inv) in {'add':add,'xor':xor}.items():
        b=fit_group(tr,op,inv)
        print(s,nm,'train',round(b[0],3),'val',round(float((op(b[1][va[0]],b[2][va[1]])==va[2]).mean()),3))
    b=fit_priority(tr,restarts=3)
    pv=np.where(b[3][va[0]]>=b[4][va[1]],b[1][va[0]],b[2][va[1]])
    print(s,'prio','train',round(b[0],3),'val',round(float((pv==va[2]).mean()),3))
