Bit 0 is the worst xor bit on skills 0 and 1, the opposite of what plain addition predicts, so the class labels may be shuffled. I will fit a free lookup table T[u(a), v(b)] with learned groupings for k=2, 4 and 8.
```python
import numpy as np
Ms=np.load("Ms.npy")
def split(M,seed=0):
    A,B=np.where(M>=0); r=np.random.RandomState(seed); p=r.permutation(len(A)); n=len(A)//5
    return (A[p[n:]],B[p[n:]],M[A[p[n:]],B[p[n:]]]),(A[p[:n]],B[p[:n]],M[A[p[:n]],B[p[:n]]])
def fitT(tr,k,restarts,seed=0,iters=10):
    A,B,Y=tr; r=np.random.RandomState(seed); best=None
    ia=[np.where(A==i)[0] for i in range(32)]; ib=[np.where(B==j)[0] for j in range(32)]
    for _ in range(restarts):
        u=r.randint(0,k,32); v=r.randint(0,k,32); T=r.randint(0,8,(k,k))
        for it in range(iters):
            C=np.zeros((k,k,8),int); np.add.at(C,(u[A],v[B],Y),1); T=C.argmax(2)
            for i in range(32):
                sc=[(T[c,v[B[ia[i]]]]==Y[ia[i]]).sum() for c in range(k)]; u[i]=int(np.argmax(sc))
            for j in range(32):
                sc=[(T[u[A[ib[j]]],c]==Y[ib[j]]).sum() for c in range(k)]; v[j]=int(np.argmax(sc))
        s=(T[u[A],v[B]]==Y).mean()
        if best is None or s>best[0]: best=(s,u.copy(),v.copy(),T.copy())
    return best
for s in range(4):
    tr,va=split(Ms[s])
    for k in [2,4,8]:
        b=fitT(tr,k,restarts={2:40,4:40,8:30}[k],seed=s)
        print(s,'k',k,'train',round(float(b[0]),3),'val',round(float((b[3][b[1][va[0]],b[2][va[1]]]==va[2]).mean()),3))
        if k==8: np.savez(f"T{s}.npz",u=b[1],v=b[2],T=b[3])
    d=np.load(f"T{s}.npz"); print(d['T'].tolist()); print(d['u'].tolist()); print(d['v'].tolist())
