    return (A[p[n:]],B[p[n:]],M[A[p[n:]],B[p[n:]]]),(A[p[:n]],B[p[:n]],M[A[p[:n]],B[p[:n]]])
def polish(A,B,Y,u,v,k,ia,ib,iters=6):
    for it in range(iters):
        C=np.zeros((k,k,8),int); np.add.at(C,(u[A],v[B],Y),1); T=C.argmax(2)
        for i in range(32):
            u[i]=int(np.argmax([(T[c,v[B[ia[i]]]]==Y[ia[i]]).sum() for c in range(k)]))
        for j in range(32):
            v[j]=int(np.argmax([(T[u[A[ib[j]]],c]==Y[ib[j]]).sum() for c in range(k)]))
    C=np.zeros((k,k,8),int); np.add.at(C,(u[A],v[B],Y),1); T=C.argmax(2)
    return T,(T[u[A],v[B]]==Y).mean()
def ils(tr,k,budget,seed=0,start=None):
    A,B,Y=tr; r=np.random.RandomState(seed)
    ia=[np.where(A==i)[0] for i in range(32)]; ib=[np.where(B==j)[0] for j in range(32)]
    t0=time.process_time(); best=None
    if start is not None:
        u,v=start[0].copy(),start[1].copy(); T,s=polish(A,B,Y,u,v,k,ia,ib); best=(s,u,v,T)
    while time.process_time()-t0<budget:
        if best is None or r.rand()<.1:
            u=r.randint(0,k,32); v=r.randint(0,k,32)
        else:
            u=best[1].copy(); v=best[2].copy()
            n=r.randint(2,9)
            u[r.randint(0,32,n)]=r.randint(0,k,n); v[r.randint(0,32,n)]=r.randint(0,k,n)
        T,s=polish(A,B,Y,u,v,k,ia,ib)
        if best is None or s>best[0]: best=(s,u.copy(),v.copy(),T.copy())
    return best
''')
