        if bestc!=old:
            C[old]-=R[i]; C[bestc]+=R[i]; u[i]=bestc; improved=True
    return improved
def rowcounts(A,B,Y,v,k):
    R=np.zeros((32,k,8),int); np.add.at(R,(A,v[B],Y),1); return R
def colcounts(A,B,Y,u,k):
